  /* ---------------- i18n helpers ---------------- */
  // App language (settings.lang) drives the UI; document language (settings.docLang) drives the
  // fixed texts of quotations, contracts, SOAs, invoices and the monthly report.
  const LANG_LS = 'eksakto_lang';
  const I18N = { fil: FIL, en: EN };
  function savedLang() { try { return localStorage.getItem(LANG_LS) || ''; } catch (e) { return ''; } }
  function appLang() {
    let l = '';
    try { l = (state && state.settings && state.settings.lang) || ''; } catch (e) { /* state not ready yet */ }
    l = l || savedLang();
    return l === 'en' ? 'en' : 'fil';
  }
  function docLang() {
    let l = '';
    try { l = (state && state.settings && state.settings.docLang) || ''; } catch (e) { /* state not ready yet */ }
    return l === 'fil' ? 'fil' : 'en';
  }
  const I18N_DEV = /^(localhost|127\.0\.0\.1)$/.test(location.hostname);
  const i18nWarned = {};
  function tl(lang, id, vars) {
    // Singular form: when the count is 1 and an "_one" text exists, use it.
    if (vars && (Number(vars.n) === 1 || Number(vars.days) === 1) && I18N[lang] && I18N[lang][id + '_one'] != null) id = id + '_one';
    let s = I18N[lang] && I18N[lang][id];
    if (s == null) {
      s = FIL[id];
      if (s == null) s = id;
      if (I18N_DEV && !i18nWarned[id]) { i18nWarned[id] = 1; console.warn('i18n: missing ' + lang + ' text for ' + id); }
    }
    if (vars) s = s.replace(/\{([A-Za-z_0-9]+)\}/g, (m, k) => (Object.prototype.hasOwnProperty.call(vars, k) ? String(vars[k]) : m));
    return s;
  }
